//! Independent authoritative inventory boundary; actual factory/cache/native bindings remain separate.
use gielinor_world::{grinding,held_item_conversion::Rule,tool_crafting::{Recipe,Job,Failure},held_use::{Handler,Scope,Type,Request},inventory::{Item,Catalog},simulation::{World,PlayerData,ActorId,Action,WorldEvent},stats::Stats,npc::RandomSource,CoordGrid};
const ROWS:[(i32,i32,u8,u8);9]=[(36,33,1,2),(38,32,1,2),(596,594,1,6),(4529,4531,4,3),(4532,4534,4,3),(4522,4524,12,3),(4537,4539,26,3),(4548,4550,49,3),(5014,5013,65,4)];
struct NoDraw;impl RandomSource for NoDraw{fn below(&mut self,_:u32)->u32{panic!("deterministic zero-XP lighting must not draw RNG")}}
fn fixture(i:usize,reverse:bool)->(World,ActorId,Request,Recipe){let(raw,out,level,op)=ROWS[i];let mut w=World::default();w.collision.allocate(3200,3200,0);let mut stats=Stats::default();stats.set_base(3,10);stats.set_current(3,10);stats.set_base(11,level as i8);stats.set_current(11,level as i8);stats.set_base(12,1);stats.set_current(12,0);let mut d=PlayerData::new(1,"Independent light inventory".into(),CoordGrid::new(3200,3200,0).unwrap(),stats);d.xp_rate_hundreds=0;
 for s in 0..28{d.inventory.restore_slot(s,Some(Item{id:1931,count:1,vars:0})).unwrap();}for(s,id)in[(0,590),(1,590),(17,raw),(26,raw)]{d.inventory.restore_slot(s,Some(Item{id,count:1,vars:0})).unwrap();}
 w.queue_login(1,d).unwrap();w.tick().unwrap();let a=w.actors().next().unwrap();w.set_membership(a,true).unwrap();let r=Recipe{skill:11,exchange:grinding::Recipe{tool:590,input:raw,output:out,members:true,animation:None},level,xp_tenths:0,output_count:1,ticks:0,name:"independent light",action:"light",failure:None};for id in[590,raw]{w.held_use_types.insert(id,Type{id,content:-1});}w.held_use_handlers.register(Scope::Types,590,raw,Handler::ToolCraftingImmediate(r)).unwrap();w.empty_containers.insert(out,Rule{output:raw,members:true,button_operation:op,message:Some("Independent extinguish acknowledgement")});w.drain_events();let h=if reverse{Request{selected_slot:17,selected_id:raw,target_slot:0,target_id:590}}else{Request{selected_slot:0,selected_id:590,target_slot:17,target_id:raw}};(w,a,h,r)}
#[test]
fn eighteen_full_bag_roundtrips_use_firemaking_not_crafting_and_preserve_zero_reward(){let mut cases=0;for i in 0..9{for reverse in[false,true]{let(mut w,a,h,r)=fixture(i,reverse);let before=w.data(a).unwrap().clone();let mut expected=before.inventory.clone();expected.restore_slot(17,Some(Item{id:r.exchange.output,count:1,vars:0})).unwrap();let job=Job{recipe:r,tool_slot:0,input_slot:17};let(p,good)=job.resolve(&before.inventory,&Catalog::default(),&before.stats,0,true,&mut NoDraw).unwrap();assert!(good);assert_eq!(p.inventory,expected);assert_eq!(p.stats,before.stats);assert!(p.advancement.is_none());let clock=w.clock.0;w.prepare_held_use(a,h).unwrap();w.finish_held_use(a,h).unwrap();assert_eq!(w.clock.0,clock);assert_eq!(w.data(a).unwrap().inventory,expected);assert_eq!(w.data(a).unwrap().stats,before.stats);assert!(w.take_tool_crafting_request(a).unwrap().is_none());assert!(!w.drain_events().iter().any(|e|matches!(e,WorldEvent::SkillAdvanced{..}|WorldEvent::PlayerCombatAnimation{..})));assert!(w.finish_held_use(a,h).is_err());
 w.data_mut(a).unwrap().stats.set_current(11,0);let unlight_stats=w.data(a).unwrap().stats.clone();w.drain_events();w.submit(a,Action::ConvertHeldItem{slot:17,item:r.exchange.output}).unwrap();w.tick().unwrap();assert_eq!(w.data(a).unwrap().inventory,before.inventory);assert_eq!(w.data(a).unwrap().stats,unlight_stats);let events=w.drain_events();assert_eq!(events.iter().filter(|e|matches!(e,WorldEvent::GameMessage{text,..} if text=="Independent extinguish acknowledgement")).count(),1);assert!(!events.iter().any(|e|matches!(e,WorldEvent::SkillAdvanced{..})));for _ in 0..6{w.tick().unwrap();}assert_eq!(w.data(a).unwrap().inventory,before.inventory);assert_eq!(w.data(a).unwrap().stats,unlight_stats);cases+=1;
 }}assert_eq!(cases,18);}
#[test]
fn two_hundred_sixteen_lighting_refusals_preserve_selected_and_duplicate_items(){let mut cases=0;for i in 0..9{for reverse in[false,true]{for mode in 0..12{let(mut w,a,h,r)=fixture(i,reverse);w.prepare_held_use(a,h).unwrap();match mode{0=>w.set_membership(a,false).unwrap(),1=>{w.data_mut(a).unwrap().stats.set_current(11,r.level as i8-1);w.data_mut(a).unwrap().stats.set_current(12,99);},2=>{w.data_mut(a).unwrap().inventory.restore_slot(0,None).unwrap();},3=>{w.data_mut(a).unwrap().inventory.restore_slot(17,Some(Item{id:r.exchange.input,count:1,vars:1})).unwrap();},4=>{w.data_mut(a).unwrap().inventory.restore_slot(0,Some(Item{id:590,count:1,vars:1})).unwrap();},5=>{w.data_mut(a).unwrap().inventory.restore_slot(17,Some(Item{id:1931,count:1,vars:0})).unwrap();},6=>{w.data_mut(a).unwrap().inventory.restore_slot(17,Some(Item{id:r.exchange.input,count:2,vars:0})).unwrap();},7=>{w.object_types.dummy.insert(r.exchange.output);},8=>w.data_mut(a).unwrap().inventory.placeholders=true,9=>w.set_modal_open(a,true).unwrap(),10=>w.request_logout(a).unwrap(),_=>w.delay_player(a,3).unwrap()}
 let before=w.data(a).unwrap().clone();let _=w.finish_held_use(a,h);for _ in 0..6{w.tick().unwrap();}assert_eq!(w.data(a).unwrap().inventory,before.inventory,"row{i} mode{mode}");assert_eq!(w.data(a).unwrap().stats,before.stats);assert!(!w.drain_events().iter().any(|e|matches!(e,WorldEvent::SkillAdvanced{..}|WorldEvent::PlayerCombatAnimation{..})));cases+=1;
 }}}assert_eq!(cases,216);}
struct Draw{roll:u32,calls:usize}impl RandomSource for Draw{fn below(&mut self,n:u32)->u32{assert_eq!(n,256);self.calls+=1;self.roll}}
#[test]
fn generic_stat_nine_success_failure_rewards_and_events_never_route_to_crafting(){for good in[false,true]{let(mut w,a,h,mut r)=fixture(0,false);r.skill=9;r.level=13;r.xp_tenths=15;r.ticks=1;r.failure=Some(Failure{output:968,xp_tenths:5,low:100,high:245,message:"Independent synthetic stat failure"});w.held_use_handlers=Default::default();w.held_use_handlers.register(Scope::Types,590,36,Handler::ToolCrafting(r)).unwrap();{let d=w.data_mut(a).unwrap();d.xp_rate_hundreds=125;d.stats.set_base(9,13);d.stats.set_current(9,13);d.stats.set_fine_xp(9,18330).unwrap();}let before=w.data(a).unwrap().clone();w.prepare_held_use(a,h).unwrap();w.finish_held_use(a,h).unwrap();let mut draw=Draw{roll:if good{0}else{255},calls:0};w.tick_with_random(&mut draw).unwrap();assert_eq!(draw.calls,0);w.tick_with_random(&mut draw).unwrap();assert_eq!(draw.calls,1);let mut expected=before.inventory.clone();expected.restore_slot(17,Some(Item{id:if good{33}else{968},count:1,vars:0})).unwrap();let mut stats=before.stats.clone();stats.set_fine_xp(9,18330+if good{18}else{6}).unwrap();assert_eq!(w.data(a).unwrap().inventory,expected);assert_eq!(w.data(a).unwrap().stats,stats);let e=w.drain_events();assert_eq!(e.iter().filter(|e|matches!(e,WorldEvent::SkillAdvanced{skill:9,..})).count(),1);assert!(!e.iter().any(|e|matches!(e,WorldEvent::SkillAdvanced{skill:12,..})));}}
